#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

using namespace std;

#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REP(i, n) FOR(i, 0, n)

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    getline(cin, s);

    int k;
    cin >> k;

    int n = static_cast<int>(s.length());
    int ans = 0;

    s.resize(n + k, '}');

    REP(i, n + k) {
        REP(j, i) {
            if (s[i] == s[j] || s[i] == '}') {
                int a = j, b = i;
                while (a != i && b < static_cast<int>(s.length()) &&
                       (s[a] == s[b] || s[b] == '}')) {
                    ++a;
                    ++b;
                }
                if (a == i)
                    ans = max(ans, (i - j) * 2);
            }
        }
    }

    cout << ans;
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    getline(cin, s);

    long long k;
    if (!(cin >> k)) return 0;

    const long long n = static_cast<long long>(s.size());
    const long long total = n + k;
    long long answer = 0;

    for (long long start = 0; start <= n; ++start) {
        long long length = (total - start) / 2;
        if (length >= n - start) {
            answer = max(answer, 2 * length);
        }
    }

    for (long long length = 1; length < n; ++length) {
        long long matching = 0;

        for (long long start = n - length - 1; start >= 0; --start) {
            if (s[start] == s[start + length])
                ++matching;
            else
                matching = 0;

            long long required = min(length, n - start - length);

            if (start + 2 * length <= total && matching >= required) {
                answer = max(answer, 2 * length);
            }
        }
    }

    cout << answer;
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    getline(cin, s);
    if (!s.empty() && s.back() == '\r')
        s.pop_back();

    long long k;
    cin >> k;

    const int n = static_cast<int>(s.size());
    const long long total = static_cast<long long>(n) + k;

    if (k >= n) {
        cout << 2 * (total / 2);
        return 0;
    }

    long long answer = 2 * k;
    const int maxHalf = static_cast<int>(total / 2);

    for (int d = static_cast<int>(k) + 1; d <= maxHalf; ++d) {
        const long long latestStart = total - 2LL * d;
        int matchingRun = 0;

        for (int j = n - d - 1; j >= 0; --j) {
            if (s[j] == s[j + d])
                ++matchingRun;
            else
                matchingRun = 0;

            if (j <= latestStart) {
                const int required = min(d, n - j - d);
                if (matchingRun >= required) {
                    answer = max(answer, 2LL * d);
                    break;
                }
            }
        }
    }

    cout << answer;
    return 0;
}

